function sparse = KeepFirst(dense,N)% KeepFirst -- Kill (set to zero) all but N first elements%  Usage%    sparse = KeepFirst(dense,N)%	sparse    = dense .* (1:length(dense) <= N);        %   % Part of WaveLab Version 802% Built Sunday, October 3, 1999 8:52:27 AM% This is Copyrighted Material% For Copying permissions see COPYING.m% Comments? e-mail wavelab@stat.stanford.edu%       